/// <summary>
/// The one thing the model does not tell you about an automation slice — and on THIS pattern the book
/// answers it out loud, which no other slice in the kit can say:
///
///   > "Although it is modeled as Event, Read Model and Processor — the whole cycle of reservation and
///   >  execution can be done within one single web-request."   — Understanding EventSourcing, ch. 36
///
/// So this folder measures TWO mechanisms rather than four, and the second one is not in the automation
/// folder's table at all:
///
///   <c>in-request</c>   the request that produced the trigger event runs the cycle before it answers.
///                       No daemon, no subscription, no clock, nothing to get wrong — and NO RECORD OF
///                       INTENT outside the moment, so a process that dies between the two commits leaves
///                       a reserved unit nobody will ever execute or give back.
///   <c>subscription</c> Marten ISubscription on SlotReserved. Durable checkpoint, so a host that was down
///                       catches up; costs the async daemon. The drawn shape.
///
/// Both satisfy every GWT unchanged, because the GWTs name the COMMAND and neither mechanism changes what
/// the command does. What differs is what happens when nobody is looking, which is what ExecutionModeTests
/// measures.
///
/// TWO RULES THAT HOLD FOR EVERY CHOICE, both inherited from reference-implementations/automation/:
///   * a clock must be absent in tests. There is no clock here, so this is free.
///   * the run must be safe to repeat. Both mechanisms are at-least-once and the decider carries both
///     guards for it.
/// </summary>
public static class IssueGrantWakeup
{
    public const string Setting = "Automation:Wakeup";

    public enum Mechanism
    {
        /// <summary>Nothing wakes it. What the test fixture sets, so a GWT drives RunIssueGrant itself.</summary>
        None,
        /// <summary>The reserve request runs the whole cycle. The book's own sentence.</summary>
        InRequest,
        /// <summary>Marten ISubscription on SlotReserved. The drawn shape.</summary>
        Subscription,
    }

    public static Mechanism Chosen { get; private set; } = Mechanism.None;

    /// <summary>
    /// Registers the todo Views ASYNC instead of Inline. There is exactly one caller and it is a test:
    /// <c>ExecutionModeTests.CONTROL_an_async_todo_view_silently_loses_the_work</c>, which reproduces the
    /// hazard of Understanding EventSourcing ch. 32 so that ViewRegistrations' departure from Marten's
    /// multi-stream default is MEASURED rather than argued.
    ///
    /// A knob whose only user is a control test is a smell, and it is the lesser one: the alternative is a
    /// comment claiming a failure mode that nothing demonstrates, which is how a kit acquires folklore.
    /// </summary>
    public const string TodoViewAsyncSetting = "Automation:TodoViewAsync";

    public static bool TodoViewAsync { get; private set; }

    /// <summary>
    /// Resolves WHICH mechanism was chosen. Called FIRST in Program.cs, before every Configure hook below
    /// asks for it — resolved later, a mechanism sets its flags on callbacks that have already run, with
    /// no error and no wakeup. That ordering bug is real and cost the automation folder a debugging
    /// session; it is why Choose exists as a separate step at all.
    ///
    /// AN UNKNOWN VALUE THROWS. A typo that quietly means "None" is a system where nothing is ever
    /// executed and every test still passes, which is the exact defect this seam exists to prevent.
    /// </summary>
    public static void Choose(IConfiguration config)
    {
        Chosen = (config[Setting] ?? "").Trim().ToLowerInvariant() switch
        {
            "in-request" or "inrequest" => Mechanism.InRequest,
            "subscription" => Mechanism.Subscription,
            "" or "false" or "none" => Mechanism.None,
            var other => throw new InvalidOperationException(
                $"{Setting}='{other}' is not a mechanism. Use in-request, subscription, or false."),
        };

        TodoViewAsync = string.Equals(config[TodoViewAsyncSetting], "true", StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>Hosted services and anything needing the app builder.</summary>
    public static void RegisterServices(WebApplicationBuilder builder)
    {
        // NOT A WAKEUP CONCERN, and it is here because this is the only scaffolded hook that gets the
        // builder — Program.cs is emit. A real system replaces this line with its own executor; the
        // stand-in exists so the compensating path is reachable end to end. See IGrantExecutor.
        builder.Services.AddSingleton<IGrantExecutor, StandInGrantExecutor>();
    }

    /// <summary>
    /// The lifecycle of this slice's todo View. The fallback ViewRegistrations passes is INLINE — a
    /// deliberate departure from codegen's multi-stream default, argued there — and no mechanism here
    /// needs to override it. RaiseSideEffects would; it is not one of the two.
    /// </summary>
    public static ProjectionLifecycle LifecycleOf(ProjectionLifecycle fallback) =>
        TodoViewAsync ? ProjectionLifecycle.Async : fallback;

    /// <summary>Marten options: a projection lifecycle, a subscription registration.</summary>
    public static void ConfigureMarten(StoreOptions opts) { }

    /// <summary>The store: AddAsyncDaemon, which a subscription needs.</summary>
    public static void ConfigureStore(MartenServiceCollectionExtensions.MartenConfigurationExpression marten)
    {
        if (Chosen != Mechanism.Subscription) return;

        marten.AddAsyncDaemon(DaemonMode.Solo);

        // FILTERED TO SlotReserved. The trigger re-reads the whole todo View on every wakeup, so being
        // woken by GrantIssued as well would do the same work twice and find nothing the second time —
        // harmless, but a wasted round trip per grant and one wrong guard away from a loop.
        marten.AddSubscriptionWithServices<IssueGrantSubscription>(
            ServiceLifetime.Singleton, o => o.IncludeType<SlotReserved>());
    }

    /// <summary>The Marten-to-Wolverine integration: where event forwarding would be switched on.</summary>
    public static void ConfigureIntegration(MartenIntegration integration) { }

    /// <summary>Wolverine options: discovery, policies.</summary>
    public static void ConfigureWolverine(WolverineOptions opts) { }
}

/// <summary>
/// Wakes the trigger from the durable event stream. Its distinctive property is not speed — it is having a
/// RECORD OF INTENT OUTSIDE THE MOMENT: the checkpoint is a row in the database, so a host that was down
/// when the reservation was taken still executes it when it comes back. In-request has nothing to come
/// back to.
///
/// It also COALESCES — one wakeup per event page rather than per event — which suits a trigger that works
/// the whole list anyway.
///
/// The bus is resolved from IServiceProvider rather than injected: Marten builds a subscription during
/// store construction, and Wolverine's message store IS Marten, so a constructor-injected IMessageBus
/// reaches for a Lazy that is still being created. Documented in reference-implementations/automation/.
/// </summary>
public sealed class IssueGrantSubscription(IServiceProvider services) : ISubscription
{
    public async Task<IChangeListener> ProcessEventsAsync(
        EventRange page,
        ISubscriptionController controller,
        IDocumentOperations operations,
        CancellationToken cancellationToken)
    {
        if (page.Events.Count == 0) return NullChangeListener.Instance;

        await using var scope = services.CreateAsyncScope();
        await scope.ServiceProvider.GetRequiredService<IMessageBus>()
            .InvokeAsync(new RunIssueGrant(), cancellationToken);

        return NullChangeListener.Instance;
    }

    public ValueTask DisposeAsync() => new();
}
